package com.uitopic.rumbo.analytics.domain.model.aggregates;

import com.uitopic.rumbo.analytics.domain.model.valueobjects.EventMetadata;
import com.uitopic.rumbo.analytics.domain.model.valueobjects.NavigationEventType;

import java.time.Duration;
import java.time.Instant;
import java.util.Objects;
import java.util.Optional;
import java.util.UUID;

/**
 * Aggregate root for one fact of a navigation session. It is immutable once created, always belongs to a session, a
 * site and a valid type, and never references the user: the session identifier is generated by the device for the
 * trip and says nothing about who made it.
 */
public final class NavigationEvent {
  /** How far ahead of the server clock a device may be. Further ahead means its clock is wrong. */
  public static final Duration MAX_CLOCK_SKEW = Duration.ofMinutes(5);

  private final UUID id;
  private final UUID navigationSessionId;
  private final UUID siteId;
  private final UUID floorId;
  private final NavigationEventType eventType;
  private final String nodeReference;
  private final Instant occurredAt;
  private final Instant receivedAt;
  private final EventMetadata metadata;

  private NavigationEvent(UUID id, UUID navigationSessionId, UUID siteId, UUID floorId, NavigationEventType eventType,
                          String nodeReference, Instant occurredAt, Instant receivedAt, EventMetadata metadata) {
    this.id = Objects.requireNonNull(id, "id is required");
    this.navigationSessionId = Objects.requireNonNull(navigationSessionId, "navigationSessionId is required");
    this.siteId = Objects.requireNonNull(siteId, "siteId is required");
    this.floorId = floorId;
    this.eventType = Objects.requireNonNull(eventType, "eventType is required");
    this.nodeReference = nodeReference == null || nodeReference.isBlank() ? null : nodeReference.trim();
    this.occurredAt = Objects.requireNonNull(occurredAt, "occurredAt is required");
    this.receivedAt = Objects.requireNonNull(receivedAt, "receivedAt is required");
    this.metadata = metadata == null ? EventMetadata.EMPTY : metadata;
  }

  /**
   * Records a fact reported now.
   *
   * @throws IllegalArgumentException if it happened after {@code receivedAt} plus {@link #MAX_CLOCK_SKEW}
   */
  public static NavigationEvent record(UUID id, UUID navigationSessionId, UUID siteId, UUID floorId,
                                       NavigationEventType eventType, String nodeReference, Instant occurredAt,
                                       EventMetadata metadata, Instant receivedAt) {
    if (occurredAt != null && occurredAt.isAfter(receivedAt.plus(MAX_CLOCK_SKEW))) {
      throw new IllegalArgumentException("occurredAt cannot be in the future");
    }
    return new NavigationEvent(id, navigationSessionId, siteId, floorId, eventType, nodeReference, occurredAt,
      receivedAt, metadata);
  }

  /** Rebuilds an event read from persistence. */
  public static NavigationEvent restore(UUID id, UUID navigationSessionId, UUID siteId, UUID floorId,
                                        NavigationEventType eventType, String nodeReference, Instant occurredAt,
                                        Instant receivedAt, EventMetadata metadata) {
    return new NavigationEvent(id, navigationSessionId, siteId, floorId, eventType, nodeReference, occurredAt,
      receivedAt, metadata);
  }

  public boolean isOfType(NavigationEventType type) { return eventType == type; }

  public UUID id() { return id; }
  public UUID navigationSessionId() { return navigationSessionId; }
  public UUID siteId() { return siteId; }
  public Optional<UUID> floorId() { return Optional.ofNullable(floorId); }
  public NavigationEventType eventType() { return eventType; }
  public Optional<String> nodeReference() { return Optional.ofNullable(nodeReference); }
  public Instant occurredAt() { return occurredAt; }
  public Instant receivedAt() { return receivedAt; }
  public EventMetadata metadata() { return metadata; }
}
